import{_ as B,H as e,f as A,i as m}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第二十八封信-什么相机是最好的相机？（等效焦距）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第二十八封信-什么相机是最好的相机？（等效焦距）.md","filePath":"去无方向的信/第二十八封信-什么相机是最好的相机？（等效焦距）.md","lastUpdated":1795542896000}'),t={name:"去无方向的信/第二十八封信-什么相机是最好的相机？（等效焦距）.md"};function i(p,E,s,C,a,n){return e(),A("div",null,[...E[0]||(E[0]=[m('<h1 id="第二十八封信-什么相机是最好的相机-等效焦距" tabindex="-1">第二十八封信-什么相机是最好的相机？（等效焦距） <a class="header-anchor" href="#第二十八封信-什么相机是最好的相机-等效焦距" aria-label="Permalink to &quot;第二十八封信-什么相机是最好的相机？（等效焦距）&quot;">​</a></h1><p>生生：</p><p>你好哇。</p><p>上次提到了画幅这个概念，以全画幅为标准，比他小的，有各种尺寸的残幅，比他大的，有各种尺寸的中画幅和大画幅，看起来麻麻烦烦的，所以我最后留了一个问题：分这么多大大小小的尺寸，到底在干嘛？</p><p>这次，咱们先从最直观的开始聊起，不严谨地简单来说：画幅越大，能拍到的范围就越广。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/1.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/1.jpeg" alt=""></a></p><p>重要前提：虽然这张照片儿是全画幅拍的，但咱们假装最大的框子代表 6x9 中画幅拍的画面，中等个子的框子代表全画幅拍的画面，最小的框子代表 APS-C（残幅）拍的画面……先给自己洗洗脑，暂且这样假装一下，因为我实在是没有自己拍的中画幅的例图。</p><p>看中等个子的框子，这张照片儿是用 35mm 镜头在全画幅相机上拍的，如果还是同样的35mm 镜头，我把他装在一台残幅相机上（比如说一台 APS-C 画幅的相机），我站在同样的位置，举起相机，就只能拍到中间的那个小框子……相当于这台残幅相机把我的 35mm 镜头变成了 52.5mm 镜头。</p><p>虽然用的是 35mm 镜头，但却是 52.5mm 镜头的视觉效果，这个 52.5mm 叫“等效焦距”，也可以叫“35mm 等效焦距”……这里的“35mm”指的是上次咱们说的那个 35mm 胶片画幅。</p><p>等效焦距就是要跟全画幅看齐的意思，如果我们买全画幅相机和全画幅镜头，我们不用在意这个，因为全画幅就是标准……但如果我们买非全幅相机和非全幅镜头，我们就需要看这个叫等效焦距的数据。</p><p>拿 APS-C 画幅的相机举例子。</p><p>一枚镜头说自己的真实镜头参数是 35mm，如果我们要把他装在一台 APS-C 相机上，无所谓他是全幅镜头还是非全幅镜头，我们都要给他乘上个 1.5 或 1.6 的转换系数，最后得出来的52.5mm 或 56mm 才是这枚镜头实际的成像焦距，而 52.5mm 或 56mm 就是这枚镜头的等效焦距。</p><p>反之，如果我们在 APS-C 相机上想拥有一枚实际 35mm 成像效果的镜头，我们需要选一枚23mm 或 21.8mm 的镜头，这就是除以 1.5 或 1.6 的结果了……这枚 23mm 或 21.8mm 的镜头在全画幅相机上显然是个广角镜头，但在 APS-C 相机上就是一枚 35mm 的标准镜头。</p><p>为了简化，我之后不会再提 1.6 的事儿了，统一把 APS-C 画幅的等效焦距的转换系数认定为1.5 吧……1.5 和 1.6 只是各家厂商机型不同，传感器尺寸微微不同，导致的一点点差异而已。</p><p>下面，咱们看示意图里的中画幅，就是最大的那个框子。</p><p>APS-C 画幅的转换系数是 1.5，但只要换一种画幅，这个转换系数就会跟着变，这些网上都能查到具体数值，比如这个 6x9 的中画幅，他的转换系数是 0.43，这是什么意思？</p><p>就像刚才一样，假设，我在全画幅相机上装的这枚 35mm 镜头可以装在 6x9 的中画幅相机上，我站在同样的位置，举起相机，就能拍到比全画幅大得多的画面，相当于这枚 35mm 镜头，乘以 0.43 的转换系数，变成一枚 16mm 的镜头了。</p><p>在全画幅相机上是 35mm 标准镜头，放在中画幅相机上，他就变成大广角镜头了。</p><p>反过来说，还是一样的逻辑，如果我们想在 6x9 中画幅相机上拍出全画幅 35mm 镜头的视觉效果，我们就需要一枚 35mm÷0.43 的镜头，也就是说，在 6x9 中画幅相机上，我们需要一枚大约 80mm 的镜头，才能拍出全画幅 35mm 镜头的效果。</p><p>在这儿必须防杠声明一下了：我上面只是举例子而已，实际上，镜头可以向下兼容，但不可以向上兼容。意思是，全画幅镜头可以装在残幅相机上，但残幅镜头不能装在全画幅相机上，中画幅大画幅也是一样，我刚才说把全画幅 35mm 的镜头装在中画幅相机上，纯粹只是举例子，只是为了让你明白其中的逻辑关系。</p><p>最后给你举几个实际的例子：</p><ul><li>我经常会提到的小 GR 是一台 APS-C 画幅的相机，他有一枚固定镜头，是 28mm 的，你也知道这是我最喜欢的焦段，但这个 28mm 是“等效 28mm”，因为这台相机是 APS-C 画幅的相机。所以如果他想等效 28mm，也就是说，如果他想拍出全画幅相机配 28mm 镜头的视觉效果，他就必须配一枚 18.6mm 的镜头才可以实现。而实际上，GR 的镜头是18.3mm，跟我们的测算大差不差。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/2.png" alt=""></a></p><ul><li><p>RICOH GRⅢ</p></li><li><p>还有一个我觊觎了好多年的相机系列，富士的 X100 系列，这个系列也是 APS-C 画幅的，同时，他们也是固定镜头，35mm，但这个 35mm 是“等效 35mm”，因为这个系列的相机是 APS-C 画幅的相机，所以如果他们想等效 35mm，也就是说，如果他们想拍出全画幅相机配 35mm 镜头的视觉效果，他们就必须配一枚 _____ mm 的镜头才可以实现呢？</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/3.png" alt=""></a></p><ul><li><p>FUJIFILM X100F</p></li><li><p>把这个问题留给你，你先自己算一算。小提示：注意看镜头上的参数标识。</p></li><li><p>SONY 的黑卡 Ⅶ 是一台 1 英寸底的卡片机，官网上说这台相机的镜头焦距是 24-200mm，但他最准确的镜头参数应该是下图这样的，9mm-72mm。注意看那个“焦距”和那个“等效 35mm 画幅焦距”，所以，你能说出 1 英寸底画幅的等效焦距转换系数么？</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E4%25BA%258C%25E5%258D%2581%25E5%2585%25AB%25E5%25B0%2581%25E4%25BF%25A1-%25E4%25BB%2580%25E4%25B9%2588%25E7%259B%25B8%25E6%259C%25BA%25E6%2598%25AF%25E6%259C%2580%25E5%25A5%25BD%25E7%259A%2584%25E7%259B%25B8%25E6%259C%25BA%25EF%25BC%259F%25EF%25BC%2588%25E7%25AD%2589%25E6%2595%2588%25E7%2584%25A6%25E8%25B7%259D%25EF%25BC%2589/4.png" alt=""></a></p><ul><li>SONY RX100 Ⅶ</li></ul><p>最后的最后，我实在是闲的，还想再给你举一个大画幅的例子。</p><p>大画幅镜头最重要的一个概念其实不是焦距，而是“像场”，我只是简单提一下，不会展开讲，你可以自己去查一查，总之就跟我们前面说的“镜头可以向下兼容画幅，但不能向上兼容”是一个意思。举个小例子，一枚 8x10 的大画幅镜头，可以放在 4x5 的大画幅相机上用，但是反过来就不行。</p><p>回到咱们本来要举的关于大画幅镜头焦距的例子。</p><p>这个例子很简单，是一个问题，请问：一枚 360mm 的 8x10 大画幅镜头，是不是长焦镜头？（提示：8x10 镜头等效焦距的转换系数是 0.14）</p><p>即便我们不常用中画幅和大画幅，但如果我们知道了一种画幅的等效焦距转换系数，我们就可以马上对这种画幅的镜头焦距了如指掌了。</p><p>这封信看着应该很累，我们为什么要这么费劲巴拉地了解不同画幅上的镜头焦距？废话一样，我们前面有十几封信都是由“焦距”这个东西引出来的……不能掌握焦距，就不用谈拍照片儿的事儿了。</p><p>今天就这样，咱们有时间再继续聊。</p>',35)])])}const r=B(t,[["render",i]]);export{l as __pageData,r as default};
